public class InnerBillingViewDataFilterExpressionFactory(Action<Humidifier.Billing.BillingViewTypes.DataFilterExpression> factoryAction = null) : SubResourceFactory<Humidifier.Billing.BillingViewTypes.DataFilterExpression>
{

    internal InnerBillingViewTimeRangeFactory TimeRangeFactory { get; set; }

    internal InnerBillingViewDimensionsFactory DimensionsFactory { get; set; }

    internal InnerBillingViewTagsFactory TagsFactory { get; set; }

    protected override Humidifier.Billing.BillingViewTypes.DataFilterExpression Create()
    {
        var dataFilterExpressionResult = CreateDataFilterExpression();
        factoryAction?.Invoke(dataFilterExpressionResult);

        return dataFilterExpressionResult;
    }

    private Humidifier.Billing.BillingViewTypes.DataFilterExpression CreateDataFilterExpression()
    {
        var dataFilterExpressionResult = new Humidifier.Billing.BillingViewTypes.DataFilterExpression();

        return dataFilterExpressionResult;
    }
    public override void CreateChildren(Humidifier.Billing.BillingViewTypes.DataFilterExpression result)
    {
        base.CreateChildren(result);

        result.TimeRange ??= TimeRangeFactory?.Build();
        result.Dimensions ??= DimensionsFactory?.Build();
        result.Tags ??= TagsFactory?.Build();
    }

} // End Of Class

